using Mfop.Kernel.Auditing;

namespace Mfop.Assets.Domain;

/// <summary>
/// A street-light point. Created PENDING with a registration; becomes ACTIVE only when a different user approves it.
/// Location is stored as latitude/longitude (plus a PostGIS geometry generated by the database).
/// </summary>
public sealed class StreetLight : IAuditable
{
    private StreetLight() { }

    public StreetLight(Guid id, StreetLightAttributes attributes, string captureChannel, DateTimeOffset createdAt)
    {
        Id = id;
        LifecycleState = LifecycleStates.Pending;
        CaptureChannel = captureChannel;
        Source = "FIELD_SURVEY";
        CreatedAt = createdAt;
        Apply(attributes);
    }

    public string AuditEntityType => "street_light";

    public Guid Id { get; private set; }
    public string? AssetCode { get; private set; }
    public string LifecycleState { get; private set; } = LifecycleStates.Pending;
    public string? OperationalStatus { get; private set; }
    public decimal Latitude { get; private set; }
    public decimal Longitude { get; private set; }
    public string? AddressText { get; private set; }
    public string? CircuitRef { get; private set; }
    public string PowerSource { get; private set; } = PowerSources.Grid;
    public string? PoleMaterial { get; private set; }
    public decimal? PoleHeightM { get; private set; }
    public string? LuminaireMake { get; private set; }
    public string? LuminaireModel { get; private set; }
    public int? LuminaireWattageW { get; private set; }
    public string? LuminaireSerial { get; private set; }
    public int? SolarPanelW { get; private set; }
    public string? SolarBatteryType { get; private set; }
    public int? SolarBatteryAh { get; private set; }
    public string? SolarControllerModel { get; private set; }
    public DateOnly? InstalledOn { get; private set; }
    public string InstalledOnPrecision { get; private set; } = InstallDatePrecisions.Unknown;
    public DateOnly? WarrantyUntil { get; private set; }
    public string? Supplier { get; private set; }
    public string ResponsibleParty { get; private set; } = ResponsibleParties.Municipality;
    public string? ResponsibleEntityName { get; private set; }
    public string ObservedStatus { get; private set; } = OperationalStatuses.Unknown;
    public string Source { get; private set; } = "FIELD_SURVEY";
    public string CaptureChannel { get; private set; } = "WEB";
    public Guid? CurrentTagId { get; private set; }
    public int CurrentVersionNo { get; private set; }
    public DateTimeOffset CreatedAt { get; private set; }
    public int Version { get; private set; }

    public void Apply(StreetLightAttributes a)
    {
        Latitude = a.Latitude;
        Longitude = a.Longitude;
        AddressText = a.AddressText;
        CircuitRef = a.CircuitRef;
        PowerSource = a.PowerSource;
        PoleMaterial = a.PoleMaterial;
        PoleHeightM = a.PoleHeightM;
        LuminaireMake = a.LuminaireMake;
        LuminaireModel = a.LuminaireModel;
        LuminaireWattageW = a.LuminaireWattageW;
        LuminaireSerial = a.LuminaireSerial;
        SolarPanelW = a.SolarPanelW;
        SolarBatteryType = a.SolarBatteryType;
        SolarBatteryAh = a.SolarBatteryAh;
        SolarControllerModel = a.SolarControllerModel;
        InstalledOn = a.InstalledOn;
        InstalledOnPrecision = a.InstalledOnPrecision;
        WarrantyUntil = a.WarrantyUntil;
        Supplier = a.Supplier;
        ResponsibleParty = a.ResponsibleParty;
        ResponsibleEntityName = a.ResponsibleEntityName;
        ObservedStatus = a.ObservedStatus;
    }

    public StreetLightAttributes ToAttributes() => new(
        Latitude, Longitude, PowerSource, ResponsibleParty, InstalledOnPrecision, ObservedStatus, AddressText, CircuitRef,
        PoleMaterial, PoleHeightM, LuminaireMake, LuminaireModel, LuminaireWattageW, LuminaireSerial, SolarPanelW,
        SolarBatteryType, SolarBatteryAh, SolarControllerModel, InstalledOn, WarrantyUntil, Supplier, ResponsibleEntityName);

    /// <summary>AL2 + OS1/OS2/OS3: activation on approval.</summary>
    public void Activate(string assetCode, Guid tagId, int versionNo)
    {
        var lifecycle = AssetStateMachines.AssetLifecycle.Resolve(LifecycleState, "OnRegistrationApproved");
        if (!lifecycle.IsSuccess)
        {
            throw new InvalidOperationException(lifecycle.Error!.Message);
        }

        var command = ObservedStatus switch
        {
            OperationalStatuses.Operational => "OnRegistrationApprovedObservedOperational",
            OperationalStatuses.Faulty => "OnRegistrationApprovedObservedFaulty",
            _ => "OnRegistrationApproved",
        };
        LifecycleState = lifecycle.Value.To;
        OperationalStatus = AssetStateMachines.AssetOperationalStatus.Create(command).Value.To;
        AssetCode = assetCode;
        CurrentTagId = tagId;
        CurrentVersionNo = versionNo;
    }

    /// <summary>AL3: the registration was rejected or discarded.</summary>
    public void RejectLifecycle()
    {
        LifecycleState = AssetStateMachines.AssetLifecycle.Resolve(LifecycleState, "OnRegistrationRejectedOrDiscarded").Value.To;
    }
}
